CREATE TYPE occurrence_status AS ENUM ('NORMAL','CANCELLED');
CREATE TABLE class_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_id uuid NOT NULL REFERENCES branches(id), name varchar(120) NOT NULL, weekday integer NOT NULL CHECK (weekday BETWEEN 1 AND 7), local_start_time time NOT NULL, duration_minutes integer NOT NULL CHECK (duration_minutes > 0), default_instructor_id uuid REFERENCES users(id), default_capacity integer NOT NULL CHECK (default_capacity > 0), is_active boolean NOT NULL DEFAULT true);
CREATE TABLE class_occurrences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_id uuid NOT NULL REFERENCES class_templates(id), class_date date NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL CHECK (ends_at > starts_at), branch_id uuid NOT NULL REFERENCES branches(id), instructor_id uuid REFERENCES users(id), capacity integer NOT NULL CHECK (capacity > 0), status occurrence_status NOT NULL DEFAULT 'NORMAL', is_date_override boolean NOT NULL DEFAULT false, UNIQUE(template_id,class_date));
CREATE TABLE pass_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(120) NOT NULL, default_credits integer NOT NULL, default_valid_days integer NOT NULL, default_price numeric(12,2) NOT NULL, is_active boolean NOT NULL DEFAULT true); CREATE UNIQUE INDEX pass_products_one_active_uq ON pass_products ((true)) WHERE is_active;
CREATE TABLE passes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), member_id uuid NOT NULL REFERENCES users(id), product_id uuid NOT NULL REFERENCES pass_products(id), selling_branch_id uuid NOT NULL REFERENCES branches(id), paid_amount numeric(12,2) NOT NULL, total_credits integer NOT NULL CHECK(total_credits > 0), remaining_credits integer NOT NULL CHECK(remaining_credits BETWEEN 0 AND total_credits), starts_on date NOT NULL, expires_on date NOT NULL, issued_by uuid NOT NULL REFERENCES users(id), issued_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX class_occurrences_branch_starts_idx ON class_occurrences(branch_id,starts_at); CREATE INDEX class_occurrences_instructor_starts_idx ON class_occurrences(instructor_id,starts_at); CREATE INDEX passes_member_expiry_idx ON passes(member_id,expires_on,issued_at);
